const originalShowVocabCard=showVocabCard,originalCheckVocab=checkVocab;showVocabCard=()=>{originalShowVocabCard();['#check-vocab','#verbs-check-vocab'].forEach(selector=>{const button=document.querySelector(selector);if(button){button.innerHTML='Check answer <span>↵</span>';button.onclick=checkVocab}})};checkVocab=()=>{originalCheckVocab();const button=document.querySelector(isVerbView()?'#verbs-check-vocab':'#check-vocab');if(button){button.innerHTML=vocabCorrect?'Next word <span>→</span>':'Check answer <span>↵</span>';button.onclick=vocabCorrect?nextVocab:checkVocab}};showVocabCard();
