const originalNextMixed=nextMixed,originalCheckMixed=checkMixed;nextMixed=()=>{originalNextMixed();const button=$('#check-mixed');if(button&&!lessonComplete){button.style.display='';button.innerHTML='Check answer <span>↵</span>';button.onclick=checkMixed}};checkMixed=()=>{originalCheckMixed();const button=$('#check-mixed');if(button&&!lessonComplete){button.innerHTML=mixedCorrect?'Next question <span>→</span>':'Check answer <span>↵</span>';button.onclick=mixedCorrect?nextMixed:checkMixed}};
document.addEventListener('click',event=>{const button=event.target.closest('[data-grammar-check]');if(!button)return;const card=button.closest('[data-grammar-index]'),index=Number(card.dataset.grammarIndex);if(grammarAnswered[index]&&grammarCorrect[index]){event.preventDefault();event.stopImmediatePropagation();card.querySelector('[data-grammar-next]').click()}},true);document.addEventListener('click',event=>{const grammarCheck=event.target.closest('[data-grammar-check]'),grammarNext=event.target.closest('[data-grammar-next]');if(grammarCheck){const card=grammarCheck.closest('[data-grammar-index]'),index=Number(card.dataset.grammarIndex);setTimeout(()=>{grammarCheck.innerHTML=grammarAnswered[index]&&grammarCorrect[index]?'Next question <span>→</span>':'Check answer <span>↵</span>'},0)}if(grammarNext){const card=grammarNext.closest('[data-grammar-index]');setTimeout(()=>{card.querySelector('[data-grammar-check]').innerHTML='Check answer <span>↵</span>'},0)}},false);
