document.addEventListener('click',event=>{const button=event.target.closest('[data-grammar-check]');if(!button)return;const card=button.closest('[data-grammar-index]'),index=Number(card.dataset.grammarIndex),test=grammarLessons[index].tests[grammarTestState[index]],answer=card.querySelector('[data-grammar-answer]').value;grammarAnswered[index]=true;grammarCorrect[index]=test.answers.some(expected=>grammarNormalize(answer)===grammarNormalize(expected))},false);
