function showVocabHint(){const words=currentWords();if(!words.length)return;const w=words[vocabIndex%words.length],article=w.de.match(/^(der|die|das) /)?.[1]||'',german=w.de,english=w.en;$('#vocab-feedback').textContent=vocabMode==='translate'?'Hint · German answer: '+german+(article?' · Article: '+article:''):vocabMode==='choice'?'Hint · English answer: '+english+(article?' · Article: '+article:''):'Hint · English answer: '+english+(article?' · Article: '+article:'');$('#vocab-feedback').className='feedback hint'}
function showMixedHint(){if(!mixedQuestion)return;const q=mixedQuestion,item=q.item;let answer;if(q.kind==='grammar')answer='Grammar answer: '+item.test.answers.join(' / ');else if(q.kind==='phrase-cloze')answer='Missing German word: '+clozeFor(item).word+' · Full sentence: '+item.de;else if(q.kind.startsWith('phrase'))answer='German answer: '+item.de;else if(q.kind==='vocab-translate')answer='German answer: '+item.de;else answer='English answer: '+item.en+(item.de.match(/^(der|die|das) /)?.[1]?' · Article: '+item.de.match(/^(der|die|das) /)[1]:'');$('#mixed-feedback').textContent='Hint · '+answer;$('#mixed-feedback').className='feedback hint'}
$$('[id$="vocab-hint"]').forEach(button=>button.onclick=showVocabHint);document.querySelector('#mixed-hint-button').onclick=showMixedHint;
document.addEventListener('click',event=>{const button=event.target.closest('[data-grammar-hint]');if(!button)return;const card=button.closest('[data-grammar-index]'),index=Number(card.dataset.grammarIndex),test=grammarLessons[index].tests[grammarTestState[index]],feedback=card.querySelector('[data-grammar-feedback]');feedback.textContent='Hint: '+test.answers.join(' / ');feedback.className='grammar-test-feedback hint'},false);
const vocabularyCheckButtons=[document.querySelector('#check-vocab'),document.querySelector('#verbs-check-vocab')].filter(Boolean);vocabularyCheckButtons.forEach(button=>button.onclick=checkVocab);const vocabularyInputs=[document.querySelector('#vocab-answer'),document.querySelector('#verbs-vocab-answer')].filter(Boolean);vocabularyInputs.forEach(input=>input.onkeydown=e=>{if(e.key!=='Enter')return;e.preventDefault();if(vocabAnswered&&vocabCorrect)nextVocab();else checkVocab()});document.addEventListener('keydown',e=>{const keyArticles={'1':'der','2':'die','3':'das'},root=document.querySelector('#verbs-view.active-view')||document.querySelector('#vocabulary-view.active-view');if(!root||!keyArticles[e.key])return;const choices=root.querySelector('[id$="article-choices"]');if(!choices||choices.style.display==='none')return;e.preventDefault();const button=choices.querySelector(`[data-article="${keyArticles[e.key]}"]`);if(button)button.click()});
